  if let Some(s)=self.row_source.as_mut(){if s.terminal_is_empty(){drop(self.row_source.take());return Ok(Some(RetainedCloneStep::Progress(progress(demand(size_of::<Option<RetainedCloneSource<SealedShared<Node>>>>(),0)))));}return s.close_step(g).map(|s|Some(RetainedCloneStep::Progress(s.progress())));}
  if let Some(s)=self.list_source.as_mut(){if s.terminal_is_empty(){drop(self.list_source.take());return Ok(Some(RetainedCloneStep::Progress(progress(demand(size_of::<Option<RetainedCloneSource<PersistentList<Node>>>>(),0)))));}return s.close_step(g).map(|s|Some(RetainedCloneStep::Progress(s.progress())));}
