 fn take_messages(&mut self)->Vec<semio_framework_os_spr::MutationMessage>{Vec::new()}
 fn commit_demand(&self,_:RetainedCloneRef<'_,Diff>,_:RetainedCloneRef<'_,Document>,_:&Document,_:usize)->Result<RetirementDemand,ValueError>{Ok(demand(2*size_of::<PersistentList<Node>>()+size_of::<bool>(),0))}
 fn commit(&mut self,d:RetainedCloneRef<'_,Diff>,p:RetainedCloneRef<'_,Document>,post:&mut Document,g:RetainedCloneGrant,_:ApplyCapability)->Result<RetainedCloneStep,ValueError>{let q=self.commit_demand(d,p,post,0)?;if !fits(q,g){return Ok(RetainedCloneStep::Progress(Default::default()));}assert!(!self.committed&&self.valid);let candidate=self.prepared.take().unwrap();*self.prepared=Some(std::mem::replace(&mut post.nodes,candidate));self.committed=true;APPLY_CALLS.set(APPLY_CALLS.get()+1);Ok(RetainedCloneStep::Complete(progress(q)))}
 fn begin_close(&mut self){self.closing=true;self.begin_operation_close();}
 fn close_demand(&self,body:usize)->Result<RetirementDemand,ValueError>{if let Some(q)=self.cleanup_demand(body)?{return Ok(q);}if !self.retirement.is_empty(){return self.retirement.next_owner_demands::<Node>(false,&None,body);}if self.node.is_some(){return self.retirement.next_owner_demands::<Node>(true,&None,body);}if self.row.is_some(){return self.retirement.next_owner_demands::<SealedShared<Node>>(true,&None,body);}if self.sealed.iter().any(Option::is_some){return self.retirement.next_owner_demands::<SealedShared<String>>(true,&None,body);}if self.strings.iter().any(Option::is_some){return self.retirement.next_owner_demands::<String>(true,&None,body);}if self.candidate.is_some()||self.prepared.is_some(){return self.retirement.next_owner_demands::<PersistentList<Node>>(true,&None,body);}Ok(Default::default())}
 fn close_step(&mut self,g:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{assert!(self.closing);let q=self.close_demand(g.maximum_copy_bytes)?;if !fits(q,g){return Ok(RetainedCloneStep::Progress(Default::default()));}if let Some(s)=self.cleanup(g)?{return Ok(s);}if !self.retirement.is_empty(){return self.retirement.step_granted(g).map(|s|RetainedCloneStep::Progress(s.progress()));}if let Some(s)=self.retirement.begin_granted(&mut self.node,g)?{return Ok(RetainedCloneStep::Progress(s.progress()));}if let Some(s)=self.retirement.begin_granted(&mut self.row,g)?{return Ok(RetainedCloneStep::Progress(s.progress()));}for s in self.sealed.iter_mut(){if let Some(p)=self.retirement.begin_granted(s,g)?{return Ok(RetainedCloneStep::Progress(p.progress()));}}for s in self.strings.iter_mut(){if let Some(p)=self.retirement.begin_granted(s,g)?{return Ok(RetainedCloneStep::Progress(p.progress()));}}if let Some(s)=self.retirement.begin_granted(&mut self.candidate,g)?{return Ok(RetainedCloneStep::Progress(s.progress()));}if let Some(s)=self.retirement.begin_granted(&mut self.prepared,g)?{return Ok(RetainedCloneStep::Progress(s.progress()));}Ok(RetainedCloneStep::Complete(Default::default()))}
